arguments.command:
python3 -c '
import re

with open("/workspace/run/experiments/logs/user/kt-seeds/icepop_w067-s2/main.log") as f:
    text = f.read()

# Parse each step table
blocks = text.split("StatsLogger INFO:")
print(f"Found {len(blocks)-1} step blocks")

steps = []
for b in blocks[1:]:
    header = b.splitlines()[0].strip()
    kvs = {}
    for line in b.splitlines()[1:]:
        if "│" in line:
            parts = [p.strip() for p in line.split("│") if p.strip()]
            for i in range(0, len(parts)-1, 2):
                k, v = parts[i], parts[i+1]
                try:
                    kvs[k] = float(v)
                except ValueError:
                    kvs[k] = v
    steps.append((header, kvs))

print("All keys at step 1:", sorted(steps[0][1].keys()))
print("All keys at step 29 (epoch 1 eval):", sorted(steps[28][1].keys()))
for idx in [0, 1, 9, 19, 28, 29, 39, 49, 57, 58, 69, 79, 86]:
    h, kvs = steps[idx]
    print(f"=== {h} ===")
    for k in sorted(kvs.keys()):
        if any(w in k for w in ["reward", "loss", "kl", "mask", "clip", "ratio", "len", "eos", "grad", "entropy", "rejection", "valid"]):
            print(f"  {k}: {kvs[k]}")
'

